sys_script.script:
/**
 * Sync Filter -- before insert/update, order 200.
 *
 * Rejects a Sync Filter whose conditions cannot be evaluated the way the author meant.
 *
 * Every rule below fails SILENTLY at run time otherwise -- the filter saves, the job runs, and it
 * syncs the wrong set of workloads or none at all with nothing in the log to say why. This rule
 * is what replaces the structural safety the old Label Filter Item records gave for free, now
 * that a filter is free-text encoded queries.
 *
 * The label rules are deliberately NOT restated here. They live in
 * IllumioSyncUtils.parseLabelCondition, which is the same parse the evaluator runs, so what is
 * rejected on save and what is refused at run time cannot drift apart. Adding a rule means adding
 * it to the parser; this file picks it up for free. As of now the parser enforces:
 *
 *   - a sub-predicate is a Label Dimension and its CMDB Value and nothing else
 *     (illumio_label_dimension=<dimension>^cmdb_value=<value>)
 *   - "is" is the only operator -- no LIKE, STARTSWITH, IN, ISEMPTY, negations or ranges
 *   - no condition may have a blank value, and no OR group may be empty
 *   - a dimension must carry a value condition; a value condition must follow a dimension
 *   - ^OR may not be applied to the dimension field itself
 *
 * What stays here is everything that is a property of the RECORD rather than of the condition
 * text: the zero-terms check, and the class_mapping pairing.
 *
 * The readable rendering of the condition is NOT done here and is not stored on the record. It is
 * computed on demand for display only -- see IllumioUtilsAJAX.describeLabelCondition and the
 * "Sync Filter Describe Label Condition" client script.
 */
(function executeRule(current, previous /*null when async*/ ) {

    var syncUtils = new IllumioSyncUtils();
    var labelErrors = [];
    var mappingErrors = [];

    var labelCondition = current.getValue('label_condition');
    if (!syncUtils.isConditionEmpty(labelCondition)) {
        var parsed = syncUtils.parseLabelCondition(labelCondition);
        labelErrors = parsed.errors;

        // Parsed cleanly but produced nothing to run -- an ORDERBY on its own, for instance.
        // Saving it would look like a filter and behave like an empty one.
        if (labelErrors.length === 0 && parsed.terms.length === 0) {
            labelErrors.push('The Label Condition has no usable conditions. ' +
                'Add at least one Label Dimension condition, or clear the field.');
        }
    }

    var cmdbCondition = current.getValue('cmdb_condition');
    if (!syncUtils.isConditionEmpty(cmdbCondition) && gs.nil(current.getValue('class_mapping'))) {
        // A Class Mapping is what names the CMDB table. Without one there is nothing to run the
        // condition against. Note the converse is deliberately legal: a Label Condition with no
        // Class Mapping spans every class mapping of the PCE Configuration, which is useful.
        mappingErrors.push('A CMDB Condition needs a Class Mapping, which is what names the ' +
            'table to query. Choose a Class Mapping or clear the CMDB Condition.');
    }

    if (labelErrors.length === 0 && mappingErrors.length === 0) {
        return;
    }

    var index;
    for (index = 0; index < labelErrors.length; index++) {
        gs.addErrorMessage(labelErrors[index]);
    }
    for (index = 0; index < mappingErrors.length; index++) {
        gs.addErrorMessage(mappingErrors[index]);
    }

    if (labelErrors.length > 0) {
        current.label_condition.setError(labelErrors[0]);
    }
    if (mappingErrors.length > 0) {
        current.class_mapping.setError('Required when a CMDB Condition is set.');
    }

    current.setAbortAction(true);

})(current, previous);
